package cn.linkdeck.adb;
import android.content.Context;import android.graphics.*;import android.view.View;import java.io.*;
/** Bundled wallpaper decoded once at a bounded size; no network or per-frame image work. */
public final class TvScene extends View {
 private static Bitmap wallpaper;private final Paint p=new Paint(3);private final boolean thumbnail;private final RectF dest=new RectF();private final Path clip=new Path();
 public TvScene(Context c){this(c,false);}public TvScene(Context c,boolean thumb){super(c);thumbnail=thumb;setImportantForAccessibility(IMPORTANT_FOR_ACCESSIBILITY_NO);if(wallpaper==null){try(InputStream in=c.getAssets().open("alpine-lake.webp")){BitmapFactory.Options o=new BitmapFactory.Options();o.inSampleSize=2;wallpaper=BitmapFactory.decodeStream(in,null,o);}catch(IOException ignored){}}}
 protected void onDraw(Canvas c){float w=getWidth(),h=getHeight(),d=getResources().getDisplayMetrics().density;p.setShader(null);p.setStyle(Paint.Style.FILL);if(thumbnail)dest.set(0,0,w,h);else{dest.set(w*.035f,h*.08f,w*.965f,h*.87f);p.setColor(UiPalette.color(0xff03070c));c.drawRoundRect(dest,3*d,3*d,p);dest.inset(3*d,3*d);}clip.reset();clip.addRoundRect(dest,thumbnail?12*d:d,thumbnail?12*d:d,Path.Direction.CW);c.save();c.clipPath(clip);if(wallpaper!=null){float scale=Math.max(dest.width()/wallpaper.getWidth(),dest.height()/wallpaper.getHeight());RectF image=new RectF(dest.centerX()-wallpaper.getWidth()*scale/2,dest.centerY()-wallpaper.getHeight()*scale/2,dest.centerX()+wallpaper.getWidth()*scale/2,dest.centerY()+wallpaper.getHeight()*scale/2);c.drawBitmap(wallpaper,null,image,p);}else{p.setColor(UiPalette.color(0xff23485c));c.drawRect(dest,p);}c.restore();p.setStyle(Paint.Style.STROKE);p.setStrokeWidth(d);p.setColor(UiPalette.color(0xff4b6175));c.drawRoundRect(dest,thumbnail?12*d:d,thumbnail?12*d:d,p);if(!thumbnail){p.setColor(UiPalette.color(0xff263b4a));c.drawLine(w*.5f,h*.89f,w*.5f,h*.94f,p);p.setStrokeWidth(2*d);c.drawLine(w*.2f,h*.96f,w*.8f,h*.96f,p);p.setColor(UiPalette.color(0xff728599));p.setStrokeWidth(.5f*d);c.drawLine(w*.2f,h*.95f,w*.8f,h*.95f,p);}p.setStyle(Paint.Style.FILL);}
}
